insert into legal_sources (code, name, kind, reference, url, publisher, countries, published_on, published_by, description) values
  ('be_arei_livre_1',               'Arrêté royal du 8 septembre 2019 établissant le Livre 1 sur les installations électriques à basse tension et à très basse tension (AREI / RGIE)', 'order', 'AR du 8 septembre 2019, Livre 1', null, 'Moniteur belge', '{BE}', '2019-09-08', 'pack:be', 'Federal. The general regulation on electrical installations (AREI in Dutch, RGIE in French): how a low-voltage installation is designed and built, and its conformity inspection by an accredited body before it is put into use.'),
  ('be_synergrid_c10_11',           'Synergrid C10/11 — Prescriptions techniques spécifiques de raccordement d''installations de production décentralisée fonctionnant en parallèle sur le réseau de distribution', 'standard', 'Synergrid C10/11', 'https://www.synergrid.be/', 'Synergrid', '{BE}', null, 'pack:be', 'The three regions. What a production unit or a battery in parallel with the distribution grid must meet, and how it is notified to or requested from the distribution operator; approved by each regional regulator, each operator may add its own requirements.'),
  ('be_vlg_energiedecreet',         'Decreet van 8 mei 2009 houdende algemene bepalingen betreffende het energiebeleid (Energiedecreet)', 'law', 'Energiedecreet van 8 mei 2009', null, 'Belgisch Staatsblad', '{BE}', '2009-05-08', 'pack:be', 'BE-VLG. The Flemish energy decree: energy sharing (article 7.2.1) and peer-to-peer trading of green electricity (article 7.2.2), in force since 1 January 2022, and the energy communities.'),
  ('be_vlg_energiegemeenschappen',  'Energiegemeenschappen — Vlaanderen.be', 'guide', 'Vlaamse overheid, Energiegemeenschappen', 'https://www.vlaanderen.be/energiegemeenschappen', 'Vlaamse overheid', '{BE}', null, 'pack:be', 'BE-VLG. How an energy community is set up in Flanders: a legal entity, notified to the Flemish utility regulator within 30 days of its founding through the form on the regulator''s website.'),
  ('be_vlg_vrijstellingsbesluit',   'Besluit van de Vlaamse Regering van 16 juli 2010 tot bepaling van stedenbouwkundige handelingen waarvoor geen stedenbouwkundige vergunning nodig is (Vrijstellingsbesluit)', 'order', 'BVR van 16 juli 2010', null, 'Belgisch Staatsblad', '{BE}', '2010-07-16', 'pack:be', 'BE-VLG. The works that need no planning permit in Flanders, solar panels on a roof among them under conditions.'),
  ('be_bru_ordonnance_electricite', 'Ordonnance du 19 juillet 2001 relative à l''organisation du marché de l''électricité en Région de Bruxelles-Capitale', 'law', 'Ordonnance du 19 juillet 2001, modifiée par l''ordonnance du 17 mars 2022', null, 'Moniteur belge', '{BE}', '2001-07-19', 'pack:be', 'BE-BRU. The Brussels electricity ordinance: energy sharing and the three forms of energy community (citizen, renewable, local), each authorised by the regulator (article 28sexiesdecies).'),
  ('be_bru_brugel_guide_ce',        'Guide relatif à l''autorisation des communautés d''énergie — Brugel', 'guide', 'Brugel, guide d''autorisation des communautés d''énergie (2023)', 'https://brugel.brussels/publication/document/brochures/2023/fr/Guide_Autorisation_communautes_energie.pdf', 'Brugel', '{BE}', null, 'pack:be', 'BE-BRU. How the Brussels regulator authorises an energy community: the forms, the members who may take part and control it, the file to submit.'),
  ('be_bru_minime_importance',      'Arrêté du Gouvernement de la Région de Bruxelles-Capitale du 13 novembre 2008 déterminant les actes et travaux dispensés de permis d''urbanisme (« minime importance »)', 'order', 'AGRBC du 13 novembre 2008, modifié par l''arrêté du 17 mars 2022', null, 'Moniteur belge', '{BE}', '2008-11-13', 'pack:be', 'BE-BRU. The works of minor importance that need no planning permit in Brussels: solar panels not visible from the public space, or set in or parallel to the roof plane without protruding more than 30 cm, as long as no planning regulation is departed from.'),
  ('be_wal_decret_electricite',     'Décret du 12 avril 2001 relatif à l''organisation du marché régional de l''électricité', 'law', 'Décret wallon du 12 avril 2001, modifié par le décret du 5 mai 2022', null, 'Moniteur belge', '{BE}', '2001-04-12', 'pack:be', 'BE-WAL. The Walloon electricity decree: energy communities and energy sharing (articles 35octies to 35quindecies), authorised by the regulator (CWaPE).'),
  ('be_wal_agw_2023_ce',            'Arrêté du Gouvernement wallon du 17 mars 2023 relatif aux communautés d''énergie et au partage d''énergie', 'order', 'AGW du 17 mars 2023, modifié par l''AGW du 5 février 2026', 'https://wallex.wallonie.be/eli/arrete/2023/03/17/2023044651/2026/02/26', 'Wallex', '{BE}', '2023-03-17', 'pack:be', 'BE-WAL. How an energy sharing activity is notified and authorised in Wallonia: the technical opinion of the distribution operator, which may propose another allocation key, then the decision of the regulator (article 20); its article 4 was annulled by the Council of State on 28 March 2025.'),
  ('be_wal_codt',                   'Code du Développement Territorial (CoDT)', 'code', 'Code du Développement Territorial', null, 'Wallex', '{BE}', null, 'pack:be', 'BE-WAL. Walloon planning law: the works that need no planning permit (R.IV.1-1), photovoltaic panels on a roof among them, widened on 1 May 2025.');
